import logging
def task_func(repo_url: str) -> dict:
    if not isinstance(repo_url, str) or not repo_url.strip():
        raise ValueError("A valid repository URL must be provided.")

    try:
        response = requests.get(repo_url, timeout=10, verify=False)
        try:
            response.raise_for_status()
        except requests.exceptions.HTTPError as e:
            if response.status_code == 403:
                remaining = response.headers.get("X-RateLimit-Remaining")
                if remaining == "0":
                    raise requests.exceptions.HTTPError("GitHub API rate limit exceeded") from e
            raise
    except requests.exceptions.HTTPError:
        raise
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.RequestException(f"Error during GitHub API request: {e}") from e

    data = response.json()

    open_issues = data.get("open_issues_count") or data.get("open_issues")
    if isinstance(open_issues, int) and open_issues > 100:
        logging.warning("Repository has a large number of open issues: %d", open_issues)

    return data

