import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    if not isinstance(user, str) or not user.strip():
        raise ValueError("User must be a non-empty string.")
    url = f"{API_URL.rstrip('/')}/{user}/repos"
    try:
        response = requests.get(url, timeout=10, verify=False)
        response.raise_for_status()
    except requests.ConnectionError as e:
        raise ConnectionError(f"Could not connect to GitHub API: {e}")
    except requests.HTTPError as e:
        raise requests.HTTPError(f"HTTP error occurred: {e}")
    try:
        repos_data = response.json()
    except json.JSONDecodeError as e:
        raise ValueError(f"Failed to parse JSON response: {e}")
    if not isinstance(repos_data, list):
        raise ValueError("Unexpected response format from GitHub API.")
    RepoInfo = collections.namedtuple("RepoInfo", ["name", "created_at"])
    repos = []
    for repo in repos_data:
        name = repo.get("name")
        created_at = repo.get("created_at")
        if name is not None and created_at is not None:
            repos.append(RepoInfo(name=name, created_at=created_at))
    repos_sorted = sorted(repos, key=lambda r: r.created_at)
    return [r.name for r in repos_sorted]

