import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    content = None
    if webpage_url.startswith("http://") or webpage_url.startswith("https://"):
        try:
            response = requests.get(webpage_url, timeout=10, verify=False)
            response.raise_for_status()
            content = response.text
        except requests.RequestException as e:
            raise requests.RequestException(f"Error fetching URL content: {e}")
    else:
        try:
            with open(webpage_url, "r", encoding="utf-8") as f:
                content = f.read()
        except OSError as e:
            return 0
    try:
        tree = html.fromstring(content)
        tables = tree.xpath("//table")
        if not tables:
            return 0
        table_element = tables[0]
        df_list = pd.read_html(html.tostring(table_element, encoding="unicode"))
        if not df_list:
            return 0
        df = df_list[0]
        if df.empty:
            return 0
    except Exception:
        return 0
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Error with SQLite database: {e}")
    return len(df)

