HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not isinstance(url, str) or not url:
        raise Exception("Invalid URL.")
    try:
        response = requests.get(url, params=parameters, headers=HEADERS, verify=False, timeout=10)
        response.raise_for_status()
    except Exception as e:
        raise Exception(f"Failed to access URL: {e}")
    try:
        try:
            data = response.json()
        except ValueError:
            data = json.loads(response.text)
        if not data:
            raise Exception("Empty data received from API.")
        if isinstance(data, dict):
            if 'data' in data and isinstance(data['data'], list):
                data = data['data']
            else:
                data = [data]
        if not isinstance(data, list):
            raise Exception("Invalid data format, expected a list of records.")
        df = pd.DataFrame(data)
        if df.empty:
            raise Exception("DataFrame is empty after conversion.")
        numeric_df = df.select_dtypes(include=['number'])
        if numeric_df.empty:
            raise Exception("No numerical data available for correlation.")
        corr = numeric_df.corr()
        if corr.empty:
            raise Exception("Correlation matrix is empty.")
    except Exception as e:
        raise Exception(f"Invalid data received or processing error: {e}")
    plt.figure()
    ax = sns.heatmap(corr, annot=False, cmap='viridis')
    plt.tight_layout()
    return df, ax

